      {"text": "Разрезы из нескольких скважин внутри одного депоцентра.", "claims": [], "hypothesis": true},
      {"text": "Положение скважин относительно устья крупной реки.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Набор повторяющихся элементов разреза, сопоставленных между скважинами.", "claims": [], "hypothesis": true},
      {"text": "Оценка масштаба цикла: лопасть или вся дельта.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
